insert into public.failure_patterns(id,title,symptom,root_cause,corrected_example,prevention,test_eval,source_refs,last_verified,metadata) values ('failure-05','Weak tool schema','잘못된 인자/모호한 tool 선택','도구 설명·enum·필수 필드가 약함','좁은 JSON Schema + 서버 검증','좁은 JSON Schema + 서버 검증','실패 재현용 작은 eval case를 만들고 변경 전/후의 실패율을 비교하세요.',array['anthropic-eval']::text[],'2026-09-21'::date,'{"type":"anti_pattern","bad_example":"도구 설명·enum·필수 필드가 약함 상태로 결과만 보고 운영합니다.","evidence_level":"Research/official pattern"}'::jsonb) on conflict(id) do update set title=excluded.title,symptom=excluded.symptom,root_cause=excluded.root_cause,corrected_example=excluded.corrected_example,prevention=excluded.prevention,test_eval=excluded.test_eval,source_refs=excluded.source_refs,last_verified=excluded.last_verified,metadata=excluded.metadata;
